from 写入第二遍 import add
add('24_003',1.5,'16:9，低位广角远景，武士蹲撑在画面上方中央，石铺平台向镜头延伸；镜头由远处头肩向下摇，沿白色喷流来向落到其迅速变宽的近端，武士仍留在上缘。','武士肩背猛地向前压，身体中央前端的白色液流沿石面上方直冲青的方向；流体从远处窄束迅速展宽，边缘抖出细长分叉，近处石灰被风压向两侧推开，喷流继续越过镜头近侧。','灰绿石铺地面形成强纵深，米灰残尘在地面低处分开，远处铅蓝云天位于武士后方。','上方云天冷白漫射，白色流体反光较亮，周围环境保持同场亮度。','一次喷流骤放的低沉冲风，随后带黏稠质感的连续刷响，砂粒向两侧滚开。',phase='process',node={'武士.阶段':'向青方向喷出白色液流','白色液流.阶段':'高速逼近青的位置'},meaning='原作从武士向近侧喷流的强纵深保留；它是随后落地液团的来路，不当作激光或新光源。')
add('24_004',2.5,'16:9，青侧扭腰背的中近景位于画面左侧，白色喷流沿右侧近处越过；镜头贴着她转体向侧后移，落幅同时保留睁圆双眼、收近的双臂和衣边与白流之间的窄空隙。','青的前脚向侧面踏开，腰胯先扭出去，肩胸接着收窄，双臂紧收在胸前；她睁圆眼、张嘴惊叫，头和后背一并离开喷流来向。白色液流从她背侧旁高速通过，与身体和衣物清楚分开；长马尾被气流向另一侧掀平，裙摆贴着转体方向甩开。镜尾喷流继续远去，青仍保持避让后的侧身。','灰绿石铺地面在下方倾斜掠动，后面为铅蓝天空及少量米灰尘，喷流外缘的尖白掠影短促通过。','上方云天冷白柔光，喷流经过造成短暂明暗遮换后恢复。','喷流贴身经过的压风长响与衣物拍风声，青短促吸气；没有撞击落在她身上的音响。',ja=['ひゃあっ！！！'],tone='惊叫急促拔高，发声与侧身闪避重叠。',kind='mixed',phase='process',node={'青.阶段':'侧身完全躲开喷流','双方.接触':'喷流与青身体、衣物均分离','青.新伤':'喷流未触及青、无沾染'},meaning='按用户明确纠正：完全躲开，没有碰到青。背侧尖白形是高速掠过，不能画成衣边被击中或沾染。',card={'opening':'她已认出动作并收紧防备。','beats':['脚先侧踏，腰胯带肩胸离线','圆眼惊叫，双臂收近，马尾受风掀开'],'coupling':'先启动避让，喷流才经过原先身体所在的路线。','landing':'保持侧身避过后的姿态，衣物与白流分离。'})
add('25_001',8.5,'16:9，青正面头肩近景居中，画面左下保留握紧的拳，额头到胸上入画；固定机位，眼角泪点与额前阴影清晰。','青从侧扭姿态转回面向武士，先抬起紧握的拳，眉头猛压、瞳孔缩小，脸红和眼角泪点一起涌出来；她张嘴质问，胸肩一下一下跟着重音前顶，拳头却没有挥出。后句话意越往下，她越把头往后缩，喊到最后牙关露出，拳仍绷在身前；随后吸进一口气，眼睛暂时没有移开。','铅蓝云天与下方米灰薄尘组成简洁实景背景，石地只在最下缘露出一点。','上方云天冷白柔光，额前较深阴影与脸侧红色是局部表演处理。','急促换气、拳旁护件与衣料短响；喷流远去的黏稠刷响逐步退下。',ja=['ねえ、あんたたち魔物って、こんな下劣な技しか使えないの？！','気持ち悪くて死にそう…！！'],tone='愤怒与嫌恶一起爆发，前句重音分明，后句带哭腔收紧。',kind='mixed',phase='reaction',node={'青.阶段':'躲开后愤怒回骂','青.新伤':'无新增击中或沾染'},card={'opening':'避过攻击仍使青极度嫌恶，身体还紧着。','beats':['转正、握拳压眉质问','重音前顶，嫌恶又让头往后缩','吸气后仍盯住武士'],'coupling':'拳头表态而不新增一次无结果的挥拳。','landing':'情绪高张，注意仍对着对手。'})
